package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_1 : Integer;
    in attribute io_2 : Integer;
    in attribute io_2_valid : Boolean;
    attribute mode : Integer := 2;
    attribute pwmValue : Real := 0.0;
    attribute phaseMs : Integer := 0;
    perform action tick {
      first start;
      then if io_2_valid and (io_2 == 1) {
        first start;
        then assign mode := 1;
        then assign phaseMs := 0;
      }
      then if io_2_valid and (io_2 == 2) {
        first start;
        then assign mode := 2;
        then assign phaseMs := 0;
      }
      then if mode == 1 {
        first start;
        then assign phaseMs := phaseMs + io_1;
        then assign pwmValue := (if (phaseMs / 10) == (2 * RealFunctions::floor((phaseMs / 10) / 2)) ? 1023.0 else 0.0);
      } else {
        first start;
        then assign pwmValue := 1023.0;
      }
    }
    out attribute io_0 : Real = pwmValue;
    out attribute serial_0_trigger : Boolean = true;
    out attribute serial_0_value_0 : Integer = mode;
    out attribute serial_0_value_1 : Real = pwmValue;
  }
  part system : Controller;
}
